(()=>{'use strict';const $=s=>document.querySelector(s),chart=$('#activity-chart');if(!chart)return;let days=7,metric='members',rows=[],updated=null;const nf=new Intl.NumberFormat('en'),label=d=>new Date(d+'T00:00:00Z').toLocaleDateString('en',{month:'short',day:'numeric',timeZone:'UTC'});const node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
function render(){const end=new Date();end.setUTCHours(0,0,0,0);const start=new Date(end);start.setUTCDate(start.getUTCDate()-days+1);const visible=rows.filter(r=>r.date>=start.toISOString().slice(0,10)&&r.date<=end.toISOString().slice(0,10));document.querySelectorAll('[data-days]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.days===days)));document.querySelectorAll('[data-metric]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.metric===metric)));const sum=k=>visible.some(r=>r[k]!==null)?nf.format(visible.reduce((s,r)=>s+(r[k]??0),0)):'—';$('#activity-joined').textContent=sum('joined');$('#activity-left').textContent=sum('left');$('#activity-online').textContent=visible.some(r=>r.onlinePeak!==null)?nf.format(Math.max(...visible.map(r=>r.onlinePeak??0))):'—';const legend=$('#activity-legend');legend.replaceChildren();(metric==='members'?['Joined','Left']:['Daily peak online']).forEach(t=>{const s=node('span');s.append(node('i'),document.createTextNode(t));legend.append(s);});chart.replaceChildren();chart.setAttribute('aria-busy','false');$('#activity-detail').textContent='';$('#activity-status').textContent=updated?'Last received '+new Date(updated).toLocaleString('en',{timeZone:'UTC'})+' UTC':'Historical tracking is not connected yet.';const table=$('#activity-table');table.replaceChildren();visible.forEach(r=>{const tr=node('tr');[label(r.date),r.joined,r.left,r.onlinePeak].forEach(v=>tr.append(node('td',v===null?'—':String(v))));table.append(tr);});if(!visible.length){const p=node('p','Daily history will appear here once community tracking is connected. Current Discord counts remain available above.');p.className='activity-empty';chart.append(p);const tr=node('tr'),td=node('td','No recorded days in this period.');td.colSpan=4;tr.append(td);table.append(tr);return;}
const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 760 240');svg.setAttribute('role','img');svg.setAttribute('aria-label',metric==='members'?'Daily joined and left members. Exact values are in the table below.':'Daily peak online members. Exact values are in the table below.');const add=(tag,attrs,text)=>{const e=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));if(text!==undefined)e.textContent=text;svg.append(e);return e;};const vals=visible.flatMap(r=>metric==='members'?[r.joined,r.left]:[r.onlinePeak]).filter(v=>v!==null);if(!vals.length){const p=node('p','This metric has not been recorded for the selected period.');p.className='activity-empty';chart.append(p);return;}const max=Math.max(1,...vals),x=d=>50+((Date.parse(d+'T00:00:00Z')-start.getTime())/86400000+.5)*690/days,y=v=>190-v/max*160;[0,.5,1].forEach(v=>{add('line',{x1:45,y1:y(v*max),x2:745,y2:y(v*max)});add('text',{x:36,y:y(v*max)+4,'text-anchor':'end'},nf.format(v*max));});let prev=null;visible.forEach(r=>{const a=x(r.date);if(metric==='members'){const w=Math.min(13,210/days);if(r.joined!==null)add('rect',{x:a-w-1,y:y(r.joined),width:w,height:190-y(r.joined),class:'joined'});if(r.left!==null)add('rect',{x:a+1,y:y(r.left),width:w,height:190-y(r.left),class:'left'});}else if(r.onlinePeak!==null){if(prev&&Date.parse(r.date)-Date.parse(prev.date)===86400000)add('path',{d:`M${x(prev.date)},${y(prev.onlinePeak)}L${a},${y(r.onlinePeak)}`,class:'online-line'});add('circle',{cx:a,cy:y(r.onlinePeak),r:4,class:'online-point'});prev=r;}});[0,Math.floor((days-1)/2),days-1].forEach(n=>{const d=new Date(start);d.setUTCDate(d.getUTCDate()+n);const s=d.toISOString().slice(0,10);add('text',{x:x(s),y:220,'text-anchor':'middle'},label(s));});chart.append(svg);const points=node('div');points.className='activity-points';points.setAttribute('aria-label','Inspect a recorded day');visible.forEach(r=>{const b=node('button',label(r.date));b.type='button';b.addEventListener('click',()=>{$('#activity-detail').textContent=`${label(r.date)} · Joined: ${r.joined??'not recorded'} · Left: ${r.left??'not recorded'} · Peak online: ${r.onlinePeak??'not recorded'}`;});points.append(b);});chart.append(points);}
document.querySelectorAll('[data-days]').forEach(b=>b.addEventListener('click',()=>{days=+b.dataset.days;render();}));document.querySelectorAll('[data-metric]').forEach(b=>b.addEventListener('click',()=>{metric=b.dataset.metric;render();}));fetch('/api/community-stats',{signal:AbortSignal.timeout(8000)}).then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{const valid=v=>v===null||Number.isSafeInteger(v)&&v>=0;rows=(Array.isArray(data.days)?data.days:[]).filter(r=>/^\d{4}-\d{2}-\d{2}$/.test(r.date)&&['joined','left','onlinePeak'].every(k=>valid(r[k]))).sort((a,b)=>a.date.localeCompare(b.date));updated=Number.isFinite(Date.parse(data.updatedAt))?data.updatedAt:null;render();}).catch(()=>render());})();
